using System;using ForteMove.Models.Drivers;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class Account:DriverPage{protected void Page_Load(object sender,EventArgs e){if(IsPostBack)return;ForteMove.Models.Drivers.Driver d=ServiceFactory.CreateDriverService().GetDriverByUserAccount(CurrentPrincipalContext.UserAccountId);if(d==null){Response.Redirect(ResolveUrl("~/Errors/AccessDenied.aspx"),true);return;}litName.Text=Server.HtmlEncode(d.FullName);litEmployeeNumber.Text=Server.HtmlEncode(d.EmployeeNumber);litAvailability.Text=Server.HtmlEncode(d.AvailabilityStatus==DriverAvailabilityStatus.OnLeave?"On leave":d.AvailabilityStatus.ToString());litCredentialStatus.Text=Server.HtmlEncode(d.CredentialStatus==CredentialStatus.ExpiringSoon?"Expiring soon":d.CredentialStatus.ToString());}}}
